package org.anthrobios.vespasim.core.storage

import java.util.Locale

/** Static report labels only. Recorded names, notes, bytes and diagnostics remain verbatim. */
internal class ReportText(language: String) {
    val language = language.lowercase(Locale.ROOT).substringBefore('-').substringBefore('_').takeIf { it in setOf("en", "nl", "fr") } ?: "en"
    operator fun get(label: ReportLabel, vararg values: Any?): String {
        val text = when (language) { "nl" -> label.nl; "fr" -> label.fr; else -> label.en }
        return if (values.isEmpty()) text else String.format(Locale.forLanguageTag(language), text, *values)
    }
    fun replayDifference(original: String): String = ReportLabel.entries.firstOrNull { it.name.startsWith("DIFF_") && it.nl == original }?.let { get(it) } ?: original
}

